export function getSourceContent(filename: string): string {
  const localPath = path.resolve(process.cwd(), "../../packages/sandbox/src", filename);
  if (fs.existsSync(localPath)) return fs.readFileSync(localPath, "utf-8");
  const altPath = path.resolve(process.cwd(), "packages/sandbox/src", filename);
  if (fs.existsSync(altPath)) return fs.readFileSync(altPath, "utf-8");
  if (EMBEDDED_FILES[filename]) return EMBEDDED_FILES[filename];
  throw new Error(`Runner source not found: ${filename}`);
}
